                    corners=[(e,n),(e+5,n),(e+5,n+5),(e,n+5)]
                    valid=e<x1 and all(inside(p,polygon) and self.field_height(*p)>=GRADE-.01 for p in corners)
                    if valid and start is None:start=e
                    if start is not None and not valid:
                        roads.face("charred",[(start,GRADE+.015,-n),(e,GRADE+.015,-n),
                                               (e,GRADE+.015,-n-5),(start,GRADE+.015,-n-5)],"saturday_fire_clearance")
                        start=None
