                    valid=self.road_ok(q,0) and all(BOUNDS[0]+.01<e<BOUNDS[1]-.01 and BOUNDS[2]+.01<n<BOUNDS[3]-.01 and self.field_height(e,n)>=GRADE-.01 for e,n in ((q[0]+nx*off,q[1]+nn*off) for off in (-outer,outer)))
                    if valid:run.append(q)
