    # Reject trees whose trunk is in a building. Spatially indexed once, not an
    # all-pairs search across tens of thousands of parcels and plants.
    occupied=collections.defaultdict(list)
    for b in buildings:occupied[math.floor(b["e"]/100),math.floor(b["n"]/100)].append(b)
    def unoccupied(t):
        ix,iy=math.floor(t["e"]/100),math.floor(t["n"]/100)
        for x in range(ix-1,ix+2):
            for y in range(iy-1,iy+2):
                for b in occupied[x,y]:
                    u,v=uv(t["e"]-b["e"]+ANCHOR[0],t["n"]-b["n"]+ANCHOR[1])
                    eu,ev=extents(b)
                    if abs(u)<eu/2+1 and abs(v)<ev/2+1:return False
        return True
