    outputs[OUT/"generated-assets.json"]=encoded({"inputs_sha256":digest,"assets":manifest,"files":{p.relative_to(ROOT).as_posix():{"sha256":hashlib.sha256(content).hexdigest(),"bytes":len(content)} for p,content in outputs.items()}})
