def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument("--check",action="store_true");args=parser.parse_args()
    outputs,stats=generate();different=[]
    for p,content in outputs.items():
        if args.check:
            if not p.exists() or p.read_bytes()!=content:different.append(str(p.relative_to(ROOT)))
        else:p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(content)
    print(json.dumps(stats,sort_keys=True))
    if different:
        print("1871 generated outputs differ: "+", ".join(different),file=sys.stderr);return 1
    print(f"1871 city: {len(outputs)} deterministic outputs {'verified' if args.check else 'written'}")
    return 0


if __name__=="__main__":raise SystemExit(main())
